// Experiment E16 probe (read-only): is the "3DS SysML Customization" library (DS_Views, DS_UIComponents) available
// in the open project, and what are the palette, operation and view definitions that a UML3 palette must use?
// Writes the textual notation of each requested namespace, generated by CATIA Magic itself, to a file.
// Request: uml3-textdump-request.txt next to this script:
//     outDir=<directory for the .sysml text files>
//     path=<Qualified::path>          (one line per namespace; each segment matches a declared name or short name)
// Output lines (no System.exit, no model change, no session):
//   ROOT|name|shortName|class          for root-level members whose name or short name starts with DS or Dassault
//   FOUND|path|class|ownedMembers      TEXT|path|file|chars      MISSING|path|segment not found
//   ERROR|path|stage|message           RESULT|OK|<texts written> or RESULT|FAIL|<reason>
import com.nomagic.magicdraw.core.Application
import com.dassault_systemes.modeler.kerml.model.RootNamespaces

def project = Application.getInstance().getProject()
if (project == null) return "RESULT|FAIL|no open project (run inside CATIA Magic through the SysMLv2 test harness)"
def out = new StringBuilder()
def clean = { Object t -> t == null ? "null" : t.toString().replace("|", "/").replace("\r", "").replace("\n", " ") }
def call0 = { Object o, String m -> try { (o != null && o.respondsTo(m)) ? o."$m"() : null } catch (Throwable t) { null } }
def nameOf = { e -> call0(e, "getDeclaredName") ?: call0(e, "getName") }
def shortOf = { e -> call0(e, "getDeclaredShortName") ?: call0(e, "getShortName") }

def dir = new File(System.getProperty("user.home"), "Documents/GitHub/sysmlv2-validator/utilityScripts")
def reqFile = new File(dir, "uml3-textdump-request.txt")
if (!reqFile.exists()) return "RESULT|FAIL|missing " + reqFile
String outDir = null
List<String> paths = []
List<String> rootsWanted = []   // root=<top member name>: dump the whole (unnamed) root namespace that owns it
reqFile.readLines("UTF-8").each { l ->
    if (l.startsWith("outDir=")) outDir = l.substring(7).trim()
    else if (l.startsWith("path=")) paths << l.substring(5).trim()
    else if (l.startsWith("root=")) rootsWanted << l.substring(5).trim()
}
if (!outDir || (paths.isEmpty() && rootsWanted.isEmpty())) return "RESULT|FAIL|request needs outDir= and at least one path= or root="
new File(outDir).mkdirs()

def roots = RootNamespaces.getAllRoots(project) ?: []
List topMembers = []
roots.each { r -> (call0(r, "getOwnedMember") ?: []).each { topMembers << it } }
if (topMembers.isEmpty()) return "RESULT|FAIL|no root members found (positive control failed)"
topMembers.each { m ->
    String n = nameOf(m) ?: ""
    String s = shortOf(m) ?: ""
    if (n.startsWith("DS") || n.startsWith("Dassault") || s.startsWith("DS")) {
        out.append("ROOT|" + n + "|" + s + "|" + m.getClass().getSimpleName() + "\n")
    }
}

def matches = { e, String seg -> nameOf(e) == seg || shortOf(e) == seg }

def builder
try {
    def cl = RootNamespaces.getClassLoader()
    def services = Class.forName("com.dassault_systemes.modeler.sysml.textual.textgenerator.SysMLTextGeneratorServices", true, cl)
    services.getMethod("init").invoke(null)
    builder = services.getMethod("createTextualNotationBuilder").invoke(null)
} catch (Throwable t) {
    return out.append("RESULT|FAIL|cannot create TextualNotationBuilder: " + clean(t) + "\n").toString()
}

int written = 0
// E16 run 1: toText(nested package) returned "" for all 8 packages, so the text generator needs a root namespace
rootsWanted.each { String top ->
    def root = roots.find { r -> (call0(r, "getOwnedMember") ?: []).any { matches(it, top) } }
    if (root == null) { out.append("MISSING|root:" + top + "|" + top + "\n"); return }
    out.append("FOUND|root:" + top + "|" + root.getClass().getSimpleName() + "|" + (call0(root, "getOwnedMember") ?: []).size() + "\n")
    try {
        String text = builder.toText(root)
        def f = new File(outDir, "root-" + top.replaceAll("[^A-Za-z0-9_.-]", "_") + ".sysml")
        f.write(text ?: "", "UTF-8")
        out.append("TEXT|root:" + top + "|" + f.getPath() + "|" + (text ?: "").length() + "\n")
        written++
    } catch (Throwable t) {
        out.append("ERROR|root:" + top + "|toText|" + clean(t) + "\n")
    }
}
paths.each { String path ->
    List<String> segs = path.split("::") as List
    def cur = topMembers.find { matches(it, segs[0]) }
    String missing = cur == null ? segs[0] : null
    for (int i = 1; i < segs.size() && cur != null; i++) {
        String want = segs[i]
        def next = (call0(cur, "getOwnedMember") ?: []).find { matches(it, want) }
        if (next == null) missing = want
        cur = next
    }
    if (cur == null) {
        out.append("MISSING|" + path + "|" + missing + "\n")
        return
    }
    out.append("FOUND|" + path + "|" + cur.getClass().getSimpleName() + "|" + (call0(cur, "getOwnedMember") ?: []).size() + "\n")
    try {
        String text = builder.toText(cur)
        def f = new File(outDir, path.replace("::", "__").replaceAll("[^A-Za-z0-9_.-]", "_") + ".sysml")
        f.write(text ?: "", "UTF-8")
        out.append("TEXT|" + path + "|" + f.getPath() + "|" + (text ?: "").length() + "\n")
        written++
    } catch (Throwable t) {
        out.append("ERROR|" + path + "|toText|" + clean(t) + "\n")
    }
}
out.append("RESULT|OK|" + written + "\n")
return out.toString()
